"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Noise types from another corpus: a marked, non-confirmatory check (plan summarised in docs/iterations.md, written
2026-11-24 before running; approved by the author). The replication set's main-body R-hear and S-move units, everything
as in the reliability confirmation except the background-noise recording, which comes from MS-SNSD (Freesound CC0
part, pinned commit fe61c4b): air conditioner, vacuum cleaner, washer/dryer, copy machine.

Commands (repo root; the replication set opens only with the final unlock, P1V4_FINAL_RUN=1, as in the confirmation):
  fetch     download the chosen files (train and test parts) -> data/newnoise/msnsd/, with sha256 and durations
  screen    near-identical files kept once (same length, correlation > 0.999); per type the kept files are set to the
            same RMS and joined with 1 s crossfades into one track -> data/newnoise/tracks/<type>.wav. The shared
            detector's frame probabilities for phone, doorbell, knock, footsteps, door and cabinet are recorded per
            file for information only. Changed 2026-11-24 before any system output: the plan's rule (drop a file
            with any such frame >= 0.5) dropped 45 of 48 files because the detector, trained with DEMAND backgrounds
            only, fires on unfamiliar appliance noise (frames >= 0.2 in 3-100% of a file); docs/iterations.md, 2026-11-24
  render    each main-body unit gets a type (round robin over a seeded order, per part) and a seeded start in its
            type's track (no looping); folders replication_dms0 (the unit's own SNR) and replication_dms10 ... dms40
            (10 ... 40 dB louder), rendered with the frozen generator (p1v4_units.render_versions)
  forward   the confirmation's forward (p1v4_reliability_confirm.forward, every condition) on the five folders
            -> data/p1v4/runs/reliability/newnoise/<level>/l1_<cond>.npz
  eval      the confirmation's statistics with its files redirected (level names mapped: dms0 -> dclean, dms10 ->
            dnoise10, ...) -> results/main_v04/newnoise_replication.json (claims with the registered reading rule,
            labelled as a check; per-type points of the key claims; mirror-vs-ear-damage cells per type)
"""
import copy
import hashlib
import json
import os
import random
import sys
import time
import urllib.request
from types import SimpleNamespace

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

COMMIT = "fe61c4ba0d9ac8dd7e23d719cc79f8947e1dc742"
TYPES = ("AirConditioner", "VacuumCleaner", "WasherDryer", "CopyMachine")
NAMES = {"AirConditioner": "air conditioner", "VacuumCleaner": "vacuum cleaner", "WasherDryer": "washer/dryer",
         "CopyMachine": "copy machine"}
# file numbers as listed in the repository at the pinned commit (noise_train has no CopyMachine_9)
TRAIN_FILES = {"AirConditioner": range(1, 11), "VacuumCleaner": range(1, 10), "WasherDryer": range(1, 8),
               "CopyMachine": (1, 2, 3, 4, 5, 6, 7, 8, 10)}
TEST_FILES = {"AirConditioner": range(1, 11), "VacuumCleaner": (1,), "WasherDryer": (), "CopyMachine": (1, 2)}
DL = "data/newnoise/msnsd"
TRACKS = "data/newnoise/tracks"
SPLIT = "replication"
LEVELS_NEW = {"dms0": 0, "dms10": 10, "dms20": 20, "dms30": 30, "dms40": 40}
TO_STD = {"dms0": "dclean", "dms10": "dnoise10", "dms20": "dnoise20", "dms30": "dnoise30", "dms40": "dnoise40"}
OUT = "data/p1v4/runs/reliability/newnoise"
RES = "results/main_v04/newnoise_replication.json"
SCREEN_CLASSES = ("phone", "doorbell", "knock", "footsteps", "door", "cabinet")
SCREEN_P = 0.5
XFADE_S = 1.0
SEED = 20261124
SR = 16000


def _files():
    out = []
    for t in TYPES:
        for part, n in (("noise_train", TRAIN_FILES[t]), ("noise_test", TEST_FILES[t])):
            out += [(t, part, f"{t}_{i}.wav") for i in n]
    return out


def fetch():
    import soundfile as sf
    os.makedirs(DL, exist_ok=True)
    man = []
    for t, part, name in _files():
        dst = f"{DL}/{part}/{name}"
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        if not os.path.exists(dst):
            url = f"https://raw.githubusercontent.com/microsoft/MS-SNSD/{COMMIT}/{part}/{name}"
            urllib.request.urlretrieve(url, dst + ".part")
            os.replace(dst + ".part", dst)
        info = sf.info(dst)
        man.append({"type": t, "part": part, "name": name, "path": dst, "sr": info.samplerate,
                    "channels": info.channels, "seconds": round(info.frames / info.samplerate, 2),
                    "sha256": hashlib.sha256(open(dst, "rb").read()).hexdigest()})
        print(f"{part}/{name}: {man[-1]['seconds']} s, {info.samplerate} Hz, {info.channels} ch", flush=True)
    json.dump({"commit": COMMIT, "files": man}, open(f"{DL}/manifest.json", "w"), indent=1)


def _read16(path):
    import soundfile as sf
    from scipy.signal import resample_poly
    x, sr = sf.read(path, dtype="float32")
    if x.ndim > 1:
        x = x.mean(1)
    if sr != SR:
        x = resample_poly(x, SR, sr).astype(np.float32)
    return x


def screen():
    import soundfile as sf
    import torch
    import p1v4_data as D
    import p1v4_sed as SED
    man = json.load(open(f"{DL}/manifest.json"))
    m = SED.load("data/p1v4/runs/sed/sed.pt")
    cls = [D.DET_CLASSES.index(c) for c in SCREEN_CLASSES]
    report, kept_x = [], {}
    win, hop = int(8 * SR), int(4 * SR)
    for f in man["files"]:
        x = _read16(f["path"])
        dup = next((q for q, y in kept_x.items() if len(y) == len(x) and np.corrcoef(x, y)[0, 1] > 0.999), None)
        starts = list(range(0, max(1, len(x) - win + 1), hop))
        fr = []
        with torch.no_grad():
            for i in range(0, len(starts), 16):
                b = torch.from_numpy(np.stack([SED.to32(np.pad(x[s_:s_ + win], (0, max(0, win - len(x[s_:s_ + win])))))
                                               for s_ in starts[i:i + 16]])).cuda()
                with torch.autocast("cuda", dtype=torch.bfloat16):      # as p1v4_sed.predict
                    frame, _, _ = SED.forward(m, b)
                fr.append(frame[:, :, cls].float().cpu().numpy())
        fr = np.concatenate(fr)
        keep = dup is None
        if keep:
            kept_x[f["path"]] = x
        report.append(dict(f, detector_peak={c: round(float(p), 3) for c, p in zip(SCREEN_CLASSES, fr.max((0, 1)))},
                           detector_frames_ge_05=round(float((fr.max(2) >= 0.5).mean()), 3),
                           detector_frames_ge_02=round(float((fr.max(2) >= 0.2).mean()), 3),
                           duplicate_of=dup, kept=keep))
        print(f"{f['part']}/{f['name']}: {f['seconds']} s, detector frames >= 0.5 {report[-1]['detector_frames_ge_05']}"
              + ("" if dup is None else f", near-identical to {dup} -> dropped"), flush=True)
    os.makedirs(TRACKS, exist_ok=True)
    tracks = {}
    for t in TYPES:
        xs = [kept_x[r["path"]] for r in report if r["type"] == t and r["kept"]]
        xs = [x / (np.sqrt((x ** 2).mean()) + 1e-9) * 0.05 for x in xs]
        n = int(XFADE_S * SR)
        ramp = np.linspace(0, 1, n, dtype=np.float32)
        tr = xs[0]
        for x in xs[1:]:
            tr = np.concatenate([tr[:-n], tr[-n:] * (1 - ramp) + x[:n] * ramp, x[n:]])
        path = f"{TRACKS}/{t}.wav"
        sf.write(path, tr.astype(np.float32), SR, subtype="FLOAT")
        tracks[t] = {"path": path, "files": len(xs), "seconds": round(len(tr) / SR, 1),
                     "sha256": hashlib.sha256(open(path, "rb").read()).hexdigest()}
        print(f"track {t}: {len(xs)} files, {tracks[t]['seconds']} s", flush=True)
    json.dump({"rule": f"near-identical files once (same length, correlation > 0.999); same RMS; {XFADE_S} s "
                       f"crossfades; detector probabilities recorded only (the plan's drop rule was withdrawn, see "
                       f"the docstring)", "files": report, "tracks": tracks},
              open(f"{TRACKS}/screen.json", "w"), indent=1)


# ------------------------------------------------------------------------------------------------ render

def unit_seconds(rs):
    """= p1v4_units.render_versions' length: the latest source end, point or assistant end over the versions + 1.5 s."""
    return max(max([s["end"] for s in r["sources"]] + [p["t"] for p in r["points"]] +
                   [a["end"] for a in r["assistant"]]) for r in rs) + 1.5


def assignment(rows):
    """{unit: {"type", "offset_s"}}: types round robin over a seeded order within each part; seeded starts."""
    tracks = json.load(open(f"{TRACKS}/screen.json"))["tracks"]
    by = {}
    for r in rows:
        by.setdefault(r["unit"], []).append(r)
    out = {}
    for part in ("r_hear", "s_move"):
        units = sorted(u for u, rs in by.items() if rs[0]["part"] == part)
        random.Random(f"{SEED}|{part}").shuffle(units)
        for i, u in enumerate(units):
            t = TYPES[i % len(TYPES)]
            room = tracks[t]["seconds"] - unit_seconds(by[u]) - 0.1
            assert room > 0, (u, t)
            off = random.Random(f"{SEED}|{u}").uniform(0, room)
            out[u] = {"type": t, "part": part, "offset_s": round(off, 3), "track": tracks[t]["path"]}
    return out


def render():
    import soundfile as sf
    import p1v4_data as D
    import p1v4_noise_final as NF
    import p1v4_reliability_confirm as CF
    import p1v4_units as U
    CF.check_freeze()
    NF.patch_folders()
    rows = NF.base_rows(SPLIT)
    asg = assignment(rows)
    os.makedirs(OUT, exist_ok=True)
    json.dump(asg, open(f"{OUT}/assignment.json", "w"), indent=1)
    counts = {}
    for a in asg.values():
        counts[f"{a['part']}|{a['type']}"] = counts.get(f"{a['part']}|{a['type']}", 0) + 1
    print("units per part and type:", json.dumps(counts), flush=True)
    A = U.Assets(SPLIT)
    by = {}
    for r in rows:
        by.setdefault(r["unit"], []).append(r)
    for lv, db in LEVELS_NEW.items():
        folder = f"{SPLIT}_{lv}"
        out = os.path.join(D.RENDER, folder)
        if os.path.exists(os.path.join(out, "meta.jsonl")):
            print(f"{folder}: exists, skipped", flush=True)
            continue
        os.makedirs(out, exist_ok=True)
        t0, meta = time.time(), []
        for u, rs in sorted(by.items()):
            spec = copy.deepcopy(rs[0]["spec"])
            spec["noise"], spec["noise_offset_s"] = asg[u]["track"], asg[u]["offset_s"]
            spec["snr_db"] = round(spec["snr_db"] - db, 2)
            tls = {r["version"]: SimpleNamespace(src=r["sources"], points=r["points"], assistant=r["assistant"])
                   for r in rs}
            audio, gain_db = U.render_versions(spec, tls, A)
            for r in rs:
                nr = copy.deepcopy(r)
                nr["spec"].update(noise=spec["noise"], noise_offset_s=spec["noise_offset_s"], snr_db=spec["snr_db"])
                nr["gain_db"] = gain_db
                nr["peak"] = round(float(np.abs(audio[r["version"]]).max()) / 32767, 4)
                for p in nr["points"]:
                    w = U.windows(audio[r["version"]], [p])[0]
                    assert len(w) == int(D.WIN_S * D.SR)
                    path = os.path.join(out, f"{u}_{r['version']}_p{p['k']}.wav").replace("\\", "/")
                    sf.write(path, w, U.SR, subtype="PCM_16")
                    p["window"], p["sha256"] = path, hashlib.sha256(open(path, "rb").read()).hexdigest()
                meta.append(nr)
        with open(os.path.join(out, "meta.jsonl"), "w", encoding="utf-8") as f:
            for r in meta:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")
        print(f"{folder}: {len(by)} units, {len(meta)} rows, {time.time() - t0:.0f} s", flush=True)


def forward():
    import p1v4_reliability_confirm as CF
    CF.check_freeze()
    CF.forward(SPLIT, conds=CF.ALL_CONDS, levels=tuple(LEVELS_NEW), out=OUT)


# ------------------------------------------------------------------------------------------------ eval

def eval_():
    import collections
    import p1v4_reliability_cluster as RC
    import p1v4_reliability_confirm as CF
    import p1v4_reliability_fix3 as F3
    t0 = time.time()
    CF.check_freeze()
    back = {v: k for k, v in TO_STD.items()}
    CF.fpath = lambda split, lv, cond: os.path.join(OUT, back[lv], f"l1_{cond}.npz")
    Q, dep_of, wins, ths = CF.build_items(SPLIT)
    print(f"items built ({time.time() - t0:.0f} s)", flush=True)
    asg = json.load(open(f"{OUT}/assignment.json"))
    res = {"note": "non-confirmatory check, plan docs/p1_v04_newnoise_plan.md; level names: dclean = the new noise "
                   "at the unit's own SNR (dms0), dnoise10 ... = 10 ... dB louder", "thresholds": ths,
           "cells": {}, "claims": {}, "by_type": {}, "mirror_cells": {}}
    for (part, cond, n, lv, sub), sel in Q.items():
        s_ = F3.stats(sel)
        s_["group_all_right"] = float(np.mean(list(F3.all_right(sel).values())))
        res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {}).setdefault(sub, {})[lv] = s_
    cands, specs = CF.candidate_claims(Q, wins)
    cands = CF.judge_all(cands)
    reg = json.load(open(CF.CLAIMS_OUT))
    for k, c in cands.items():
        c["registered"] = k in reg["registered"]
        c["key"] = k in reg["key"]
    res["claims"] = cands
    groups_ = collections.defaultdict(collections.Counter)
    for k, c in cands.items():
        if c["registered"]:
            groups_[k.split()[0]][c["verdict"]] += 1
    res["summary"] = {"key": {k: cands[k]["verdict"] for k in reg["key"]},
                      "key_counts": dict(collections.Counter(cands[k]["verdict"] for k in reg["key"])),
                      "registered_counts": dict(collections.Counter(c["verdict"] for c in cands.values()
                                                                    if c["registered"])),
                      "by group": {g: dict(v) for g, v in sorted(groups_.items())}}
    # per new type: the key claims' points (as the cluster script's per-environment rows)
    for prefix, sets, kind in RC.key_specs(Q):
        name = next(k for k in cands if k.startswith(prefix + ":"))
        units = sorted({x[0] for items in sets.values() for x in items})
        col = {u: i for i, u in enumerate(units)}
        A = RC.Items(sets["a"], col)
        Bi = RC.Items(sets["b"], col) if "b" in sets else None
        stat = RC.stat_of(kind, A, Bi)
        ty = np.array([asg[u]["type"] for u in units])
        per = {}
        for t in TYPES:
            inside = (ty == t).astype(float)[None, :]
            if inside.sum():
                pt = float(stat(inside)[0])
                per[t] = {"point": pt, "n_units": int(inside.sum()), "passing_side": RC.passes(pt, cands[name])}
        res["by_type"][name] = per
    # mirror-vs-ear-damage cells per new type (as p1v4_mirror_vs_ears.compute)
    cells = {}
    for p in ("r_hear", "s_move"):
        for lv in CF.LEVELS:
            for cond in ("D_off_none", "T_off_truth"):
                for sysname in ("2d", "old head"):
                    by = {}
                    for x in Q[(p, cond, sysname, lv, "all")]:
                        by.setdefault(asg[x[0]]["type"], []).append(bool(x[6]))
                    for t, xs in by.items():
                        c = cells.setdefault(f"{p}|{t}|{lv}", {"side": p, "env": t, "level": lv,
                                                              "db": int(lv[6:]) if lv != "dclean" else 0})
                        c[f"{sysname}|{cond}"] = float(np.mean(xs))
                        c["n_questions"] = len(xs)
    for c in cells.values():
        clean = cells[f"{c['side']}|{c['env']}|dclean"]
        c["ear_damage"] = clean["2d|D_off_none"] - c["2d|D_off_none"]
        c["mirror"] = c["2d|T_off_truth"] - c["old head|T_off_truth"]
        c["label_help"] = c["2d|T_off_truth"] - c["2d|D_off_none"]
    res["mirror_cells"] = cells
    res["seconds"] = round(time.time() - t0)
    json.dump(res, open(RES, "w"), indent=1, default=float)
    print("key:", json.dumps(res["summary"]["key_counts"]), "registered:",
          json.dumps(res["summary"]["registered_counts"]), flush=True)
    for k in reg["key"]:
        c = cands[k]
        bt = " ".join(f"{t[:4]} {v['point']:+.3f}{'' if v['passing_side'] else '!'}"
                      for t, v in res["by_type"][k].items())
        print(f"{c['verdict']:13s} {k[:60]:60s} {c['point']:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}] | {bt}",
              flush=True)
    for p in ("r_hear", "s_move"):
        for t in TYPES:
            row = [cells[f"{p}|{t}|{lv}"] for lv in CF.LEVELS]
            print(f"{p} {t:15s} " + "  ".join(f"{c['db']:2d}: dmg {100 * c['ear_damage']:+5.1f} mir "
                                              f"{100 * c['mirror']:+5.1f} help {100 * c['label_help']:+5.1f}"
                                              for c in row), flush=True)


if __name__ == "__main__":
    cmds = {"fetch": fetch, "screen": screen, "render": render, "forward": forward, "eval": eval_}
    if len(sys.argv) != 2 or sys.argv[1] not in cmds:
        raise SystemExit(__doc__)
    cmds[sys.argv[1]]()
